var n=`0924-sichuan-fish-in-chili-oil`;var t=`world-0924`;var a=`CN`;var s=`east-asia`;var o=4;var r=60;var g={en:`Sichuan Fish in Chili Oil`,ua:`Сичуанська риба в гострій олії`};var h={en:`Sichuan Fish in Chili Oil is a China dish made with tilapia, cornstarch, doubanjiang, garlic. This home-scale recipe assigns measured ingredients to the steps where they are used.`,ua:`Сичуанська риба в гострій олії, страва кухні країни Китай. Основні складники: тилапія, кукурудзяний крохмаль, доубаньцзян, часник. Кількості у цьому домашньому рецепті прив’язані до відповідних етапів.`};var u=[{en:`Combine the seasoning ingredients and coat the main protein or vegetables. Rest covered in the refrigerator for about 20 minutes.`,ua:`Змішайте приправи й ретельно покрийте ними м’ясо або овочі. Маринуйте під накриттям у холодильнику приблизно 20 хвилин.`,t:[`marinating`],m:20,i:[[`tilapia`,750,`g`],[`shaoxing-wine`,35,`ml`],[`ground-white-pepper`,4,`g`],[`cornstarch`,25,`g`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 12 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 12 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:12,i:[[`doubanjiang`,70,`g`],[`peanut-oil`,85,`ml`],[`garlic`,5,`clove`],[`ground-ginger`,25,`g`],[`dried-arbol-chilies`,9,`pcs`]]},{en:`Add the listed ingredients to the pot. Keep at a gentle simmer for about 12 minutes, until tender and cooked through.`,ua:`Додайте зазначені складники до каструлі. Варіть за слабкого кипіння приблизно 12 хвилин до м’якості та готовності.`,t:[`simmering`],m:12,i:[[`chicken-stock`,900,`ml`],[`napa-cabbage`,300,`g`]]},{en:`Poach the listed ingredients in barely simmering liquid for about 9 minutes until tender and cooked through.`,ua:`Пошируйте зазначені продукти в рідині без бурхливого кипіння приблизно 9 хвилин до готовності й м’якості.`,t:[`poaching`],m:9,i:[]},{en:`Cook the listed sauce ingredients over medium-low heat for about 4 minutes until aromatic and slightly thickened.`,ua:`Готуйте складники соусу на помірно слабкому вогні приблизно 4 хвилин до появи аромату та легкого загустіння.`,t:[`sauteing`,`reducing-sauce`],m:4,i:[[`sichuan-peppercorn`,8,`g`],[`chili-oil`,55,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`green-onion`,45,`g`]]}];var d={slug:n,id:t,country:`CN`,region:s,servings:4,minutes:60,title:g,text:h,steps:u};export{a as country,d as default,t as id,r as minutes,s as region,o as servings,n as slug,u as steps,h as text,g as title};